/*
  Reference data: FAQs, help topics, content blocks and legal documents.
  GENERATED by `npm run db:seed:gen` from the TypeScript fixtures in src/. Do not edit by hand: change the source and regenerate.
  Idempotent: each table is a MERGE on its key, so re-running updates rows in place and adds missing ones. It never deletes.
  Run after db/01-schema.sql:  sqlcmd -S <server> -d <db> -b -i <this file>   (plain ASCII, no code page needed)
*/
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
GO

-- ref.Faqs: 12 rows
MERGE ref.Faqs AS t
USING (VALUES
  (N'cant-see-booking', N'booking', N'I can' + NCHAR(8217) + N't see my booking', N'Bookings made by a travel agent or on another website do not appear until you link them. Use the booking number from your confirmation, the last name of the lead guest, and the departure date. If it still does not match, check for a typing slip in the number, then call Guest Services.', N'en', 1),
  (N'name-mismatch', N'documents', N'The name on my booking does not match my passport', N'A spelling fix of a few letters can be made online up to two weeks before sailing. A different name, or any change in the last two weeks, needs Guest Services, who will ask for a copy of the passport page.', N'en', 2),
  (N'pay-balance', N'payment', N'When is my final payment due, and how do I pay?', N'The date is on your trip page and in Payments. Pay by card there at any time before it. Receipts are kept in Payments afterwards.', N'en', 3),
  (N'update-card', N'payment', N'How do I change the card I pay with?', N'Add the new card in Payments. We keep only the last four digits and the expiry date, and you can remove a card at any time.', N'en', 4),
  (N'what-documents', N'documents', N'What documents do I need for this cruise?', N'This is a round trip from Fort Lauderdale. US citizens need proof of citizenship (a passport, or a certified birth certificate) and, if 16 or older, a photo ID. A passport is strongly recommended in case you must fly home from a port. Other citizens need a passport. Passports should be valid for six months after the return date.', N'en', 5),
  (N'lost-documents', N'documents', N'I have lost my passport or a travel document', N'Call Guest Services now. If you have not yet sailed they can tell you what replacement is accepted and whether you must move to a later sailing. Do not wait until embarkation day.', N'en', 6),
  (N'helper', N'account', N'Can a family member manage my booking for me?', N'Yes, if you agree. Add them as a helper and choose what they may do: view, manage documents, pay, or edit details. You can remove them at any time, and everything they change appears in your history.', N'en', 7),
  (N'notifications', N'account', N'How do I stop notifications?', N'Choose what you hear about and how in Notifications. Critical notices about itinerary changes, port closures and safety cannot be turned off, because you may need to act on them.', N'en', 8),
  (N'text-size', N'account', N'How do I make the text bigger?', N'Settings has text size, a high-contrast theme and reduced motion. They apply on every screen.', N'en', 9),
  (N'accessibility', N'onboard', N'I need accessible transport, a wheelchair or help at the port', N'Add your needs to your profile now, and tell Guest Services at least 14 days before sailing so equipment and assistance can be arranged. Tender ports such as Belize City need extra notice.', N'en', 10),
  (N'cancel', N'booking', N'I need to cancel or change my sailing', N'Changes and cancellations are handled by Guest Services so that fees and refunds are explained to you in person. Have your booking number ready.', N'en', 11),
  (N'children', N'account', N'How do my children' + NCHAR(8217) + N's accounts work?', N'Children sail on the booker' + NCHAR(8217) + N's booking. Their accounts are supervised: the booker manages their details, documents and payments.', N'en', 12)
) AS s ([Id], [Area], [Title], [Body], [Locale], [SortOrder])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Area] = s.[Area], t.[Title] = s.[Title], t.[Body] = s.[Body], t.[Locale] = s.[Locale], t.[SortOrder] = s.[SortOrder]
WHEN NOT MATCHED THEN INSERT ([Id], [Area], [Title], [Body], [Locale], [SortOrder]) VALUES (s.[Id], s.[Area], s.[Title], s.[Body], s.[Locale], s.[SortOrder]);
GO

-- ref.HelpTopics: 5 rows
MERGE ref.HelpTopics AS t
USING (VALUES
  (N'muster-en', N'safety', N'Muster drill in English', N'Go to your muster station when you hear seven short blasts and one long.' + NCHAR(10) + N'Bring your boarding pass and any medicine you need. Leave bags in your stateroom.' + NCHAR(10) + N'Show your pass to a crew member to check in.' + NCHAR(10) + N'Stay at the station until the crew say the drill is over.', N'en', 1),
  (N'muster-es', N'safety', N'Muster drill in Espa' + NCHAR(241) + N'ol', N'Vaya a su puesto de reuni' + NCHAR(243) + N'n cuando oiga siete pitidos cortos y uno largo.' + NCHAR(10) + N'Lleve su tarjeta de embarque y los medicamentos que necesite. Deje el equipaje en el camarote.' + NCHAR(10) + N'Muestre su tarjeta a un miembro de la tripulaci' + NCHAR(243) + N'n para registrarse.' + NCHAR(10) + N'Permanezca en el puesto hasta que la tripulaci' + NCHAR(243) + N'n indique que el simulacro ha terminado.', N'es', 2),
  (N'muster-fr', N'safety', N'Muster drill in Fran' + NCHAR(231) + N'ais', N'Rendez-vous ' + NCHAR(224) + N' votre poste de rassemblement au signal de sept coups brefs et un long.' + NCHAR(10) + N'Apportez votre carte d' + NCHAR(8217) + N'embarquement et vos m' + NCHAR(233) + N'dicaments. Laissez vos bagages dans la cabine.' + NCHAR(10) + N'Pr' + NCHAR(233) + N'sentez votre carte ' + NCHAR(224) + N' un membre d' + NCHAR(8217) + NCHAR(233) + N'quipage pour vous enregistrer.' + NCHAR(10) + N'Restez au poste jusqu' + NCHAR(8217) + NCHAR(224) + N' la fin de l' + NCHAR(8217) + N'exercice annonc' + NCHAR(233) + N'e par l' + NCHAR(8217) + NCHAR(233) + N'quipage.', N'fr', 3),
  (N'muster-de', N'safety', N'Muster drill in Deutsch', N'Gehen Sie bei sieben kurzen und einem langen Signalton zu Ihrer Sammelstelle.' + NCHAR(10) + N'Nehmen Sie Bordkarte und n' + NCHAR(246) + N'tige Medikamente mit. Lassen Sie Gep' + NCHAR(228) + N'ck in der Kabine.' + NCHAR(10) + N'Zeigen Sie Ihre Karte einem Besatzungsmitglied zum Einchecken.' + NCHAR(10) + N'Bleiben Sie, bis die Besatzung das Ende der ' + NCHAR(220) + N'bung bekannt gibt.', N'de', 4),
  (N'muster-zh', N'safety', N'Muster drill in ' + NCHAR(20013) + NCHAR(25991), NCHAR(21548) + NCHAR(21040) + NCHAR(19971) + NCHAR(30701) + NCHAR(19968) + NCHAR(38271) + NCHAR(30340) + NCHAR(35686) + NCHAR(25253) + NCHAR(22768) + NCHAR(21518) + NCHAR(65292) + NCHAR(35831) + NCHAR(21069) + NCHAR(24448) + NCHAR(24744) + NCHAR(30340) + NCHAR(38598) + NCHAR(21512) + NCHAR(31449) + NCHAR(12290) + NCHAR(10) + NCHAR(35831) + NCHAR(25658) + NCHAR(24102) + NCHAR(30331) + NCHAR(33337) + NCHAR(21345) + NCHAR(21644) + NCHAR(24517) + NCHAR(38656) + NCHAR(33647) + NCHAR(21697) + NCHAR(65292) + NCHAR(34892) + NCHAR(26446) + NCHAR(30041) + NCHAR(22312) + NCHAR(23458) + NCHAR(33329) + NCHAR(12290) + NCHAR(10) + NCHAR(21521) + NCHAR(33337) + NCHAR(21592) + NCHAR(20986) + NCHAR(31034) + NCHAR(30331) + NCHAR(33337) + NCHAR(21345) + NCHAR(20197) + NCHAR(30331) + NCHAR(35760) + NCHAR(12290) + NCHAR(10) + NCHAR(35831) + NCHAR(30041) + NCHAR(22312) + NCHAR(38598) + NCHAR(21512) + NCHAR(31449) + NCHAR(65292) + NCHAR(30452) + NCHAR(21040) + NCHAR(33337) + NCHAR(21592) + NCHAR(23459) + NCHAR(24067) + NCHAR(28436) + NCHAR(20064) + NCHAR(32467) + NCHAR(26463) + NCHAR(12290), N'zh', 5)
) AS s ([Id], [Area], [Title], [Body], [Locale], [SortOrder])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Area] = s.[Area], t.[Title] = s.[Title], t.[Body] = s.[Body], t.[Locale] = s.[Locale], t.[SortOrder] = s.[SortOrder]
WHEN NOT MATCHED THEN INSERT ([Id], [Area], [Title], [Body], [Locale], [SortOrder]) VALUES (s.[Id], s.[Area], s.[Title], s.[Body], s.[Locale], s.[SortOrder]);
GO

-- ref.ContentBlocks: 30 rows
MERGE ref.ContentBlocks AS t
USING (VALUES
  (N'ship-intro', N'ship', N'Sun Princess', N'Princess' + NCHAR(8217) + N's newest ship, built around the Piazza, a three-level gathering place under a glass Sphere, and the Dome, a glass-roofed pool by day and a theatre by night.', N'en', 1),
  (N'ship-highlight-1', N'ship', N'The Piazza', N'Three levels of caf' + NCHAR(233) + N's, bars and live music under the Sphere, with game shows and roaming performers.', N'en', 2),
  (N'ship-highlight-2', N'ship', N'The Dome', N'A glass dome on decks 17 and 18: a pool by day, acrobatic theatre at night, and a dance party late.', N'en', 3),
  (N'ship-highlight-3', N'ship', N'Princess Arena', N'The main show venue, seating about 900, set up three ways for different productions.', N'en', 4),
  (N'ship-highlight-4', N'ship', N'Dining included', N'Three dining rooms, the Eatery buffet, the Americana Diner, casual grills and pizza, plus 24-hour room service.', N'en', 5),
  (N'ship-highlight-5', N'ship', N'Specialty dining', N'Steakhouse, Italian, seafood, sushi, teppanyaki and a prix fixe with sea views, at an extra charge unless your package covers them.', N'en', 6),
  (N'ship-highlight-6', N'ship', N'Kids and teens', N'Firefly Park (3' + NCHAR(8211) + N'7), Neon Grove (8' + NCHAR(8211) + N'12) and The Underground (13' + NCHAR(8211) + N'17), all on decks 6 and 7.', N'en', 7),
  (N'ship-highlight-7', N'ship', N'The Sanctuary', N'An adults-only retreat on deck 18 for guests in the Sanctuary Collection of 215 staterooms.', N'en', 8),
  (N'ship-access-1', N'ship-access', N'Accessibility', N'51 accessible staterooms, with roll-in showers and wider doors.', N'en', 9),
  (N'ship-access-2', N'ship-access', N'Accessibility', N'Six elevator banks with touchscreens that assign a car; interactive deck maps beside each bank.', N'en', 10),
  (N'ship-access-3', N'ship-access', N'Accessibility', N'Wheelchair-accessible seating in the Arena, the Piazza and the main dining rooms.', N'en', 11),
  (N'ship-access-4', N'ship-access', N'Accessibility', N'Belize City is a tender port: the boats have steps, and mobility help there is limited. Ask Guest Services before you book a shore day.', N'en', 12),
  (N'ship-access-5', N'ship-access', N'Accessibility', N'Tell Princess about a wheelchair, scooter or other need at least 30 days before you sail.', N'en', 13),
  (N'port-fll', N'port', N'Fort Lauderdale', N'{"landing":"pier","blurb":"Port Everglades, about 5 miles from the airport. You board here on day 1 and leave on day 8.","bestTime":"Winter is dry and mild, the busiest season for sailing.","access":"Level terminal with wheelchair assistance from the curb. Ask for assistance when you check in online.","doThis":["Arrive at your check-in time, not earlier","Fly in the day before if you can","Stay at an airport hotel with a shuttle"],"excursions":[],"coords":[-80.1,26.1]}', N'en', 14),
  (N'port-cozumel', N'port', N'Cozumel', N'{"landing":"pier","blurb":"A Mexican island with clear water, beach clubs and the Mayan ruins at San Gervasio. The ship docks at a pier, so there is no tender.","bestTime":"November to April is dry and warm. Hurricane season runs June to November.","access":"Pier dock with a flat walk to shops and taxis. Beach clubs are a short taxi ride; most have level paths but soft sand.","doThis":["Snorkel the Palancar Reef","Visit San Gervasio ruins","Relax at a beach club","Shop at the pier"],"excursions":[{"id":"coz-snorkel","name":"Reef snorkel by boat","hours":3.5,"price":79,"access":"some"},{"id":"coz-ruins","name":"San Gervasio Mayan ruins","hours":4,"price":69,"access":"some"},{"id":"coz-beach","name":"Beach club day pass","hours":6,"price":59,"access":"easy"}],"coords":[-86.9,20.5]}', N'en', 15),
  (N'port-belize', N'port', N'Belize City', N'{"landing":"tender","blurb":"Home to the Belize Barrier Reef, Mayan temples and jungle caves. The ship anchors offshore and small boats, called tenders, carry you in.","bestTime":"February to May is driest. Showers are common the rest of the year.","access":"Tender boats have steps and a gap to step across. Guests who cannot manage steps may be unable to go ashore, and staff cannot lift a wheelchair. Plan with Guest Services before you book.","doThis":["Tour the Altun Ha temples","Tube through a jungle cave","Snorkel the reef","Visit Lamanai by river"],"excursions":[{"id":"bze-altunha","name":"Altun Ha Mayan temples","hours":4,"price":85,"access":"some"},{"id":"bze-cave","name":"Cave tubing adventure","hours":6,"price":129,"access":"demanding"},{"id":"bze-reef","name":"Barrier reef snorkel","hours":4,"price":99,"access":"some"}],"coords":[-88.2,17.5]}', N'en', 16),
  (N'port-roatan', N'port', N'Roat' + NCHAR(225) + N'n', N'{"landing":"pier","blurb":"A Honduran island with white beaches, reef snorkelling and wildlife parks. The ship docks at a pier beside shops and a beach.","bestTime":"February to June is driest. October to January is the rainy season.","access":"Level pier and a short walk to shops and a beach. Taxis and tour vans wait at the gate; vans may have a step up.","doThis":["Zip-line over the canopy","Snorkel West Bay","See sloths and monkeys","Walk the beach by the pier"],"excursions":[{"id":"rtb-zip","name":"Zip-line canopy tour","hours":3,"price":89,"access":"demanding"},{"id":"rtb-snorkel","name":"West Bay snorkel","hours":3.5,"price":75,"access":"some"},{"id":"rtb-wildlife","name":"Wildlife and monkey park","hours":3,"price":65,"access":"easy"}],"coords":[-86.5,16.3]}', N'en', 17),
  (N'port-facts-name', N'travel', N'name', N'Port Everglades, Fort Lauderdale', N'en', 18),
  (N'port-facts-address', N'travel', N'address', N'1850 Eller Drive, Fort Lauderdale, Florida', N'en', 19),
  (N'port-facts-airport', N'travel', N'airport', N'Fort Lauderdale' + NCHAR(8211) + N'Hollywood International Airport (FLL), about 5 miles away', N'en', 20),
  (N'port-facts-terminal', N'travel', N'terminal', N'Terminal 2 is the usual terminal for Sun Princess. Your terminal is confirmed at check-in.', N'en', 21),
  (N'port-facts-boarding', N'travel', N'boarding', N'Boarding opens at 11:00 AM. The ship sails at 3:00 PM, and the gangway closes 90 minutes before that.', N'en', 22),
  (N'port-facts-porters', N'travel', N'porters', N'Porters at the curb take your checked bags to your stateroom. A tip of $2 to $5 a bag is usual.', N'en', 23),
  (N'travel-mode-drive', N'travel', N'Drive and park', N'{"id":"drive","name":"Drive and park","blurb":"Park in the terminal garage and walk across a covered bridge. Drop your bags with the porters before you park.","cost":"About $20 a day to park","stepFree":true}', N'en', 24),
  (N'travel-mode-transfer', N'travel', N'Cruise transfer from the airport', N'{"id":"transfer","name":"Cruise transfer from the airport","blurb":"A coach from the airport to the terminal, booked with your cruise. Wheelchair-accessible coaches need a day' + NCHAR(8217) + N's notice.","cost":"About $26 each way, per person","stepFree":true}', N'en', 25),
  (N'travel-mode-rideshare', N'travel', N'Taxi or ride-share', N'{"id":"rideshare","name":"Taxi or ride-share","blurb":"About 15 minutes from the airport. Ask for the cruise terminal and give the terminal number.","cost":"About $25 to $35 for the car","stepFree":false}', N'en', 26),
  (N'travel-mode-shuttle', N'travel', N'Hotel shuttle', N'{"id":"shuttle","name":"Hotel shuttle","blurb":"Several nearby hotels run a free or low-cost shuttle to the terminal on sailing day. Ask when you book.","cost":"Free to about $10 each","stepFree":false}', N'en', 27),
  (N'travel-hotel-seabreeze', N'travel', N'Seabreeze Airport Inn', N'{"id":"seabreeze","name":"Seabreeze Airport Inn","blurb":"Two miles from the airport, with a free airport pickup and a shuttle to the port on sailing day.","rate":15900,"shuttle":true,"stepFree":true}', N'en', 28),
  (N'travel-hotel-harbour', N'travel', N'Harbour Palms Suites', N'{"id":"harbour","name":"Harbour Palms Suites","blurb":"Large rooms with a kitchen, 10 minutes from the terminal, with a pool.","rate":18900,"shuttle":true,"stepFree":true}', N'en', 29),
  (N'travel-hotel-beachside', N'travel', N'Beachside Courtyard', N'{"id":"beachside","name":"Beachside Courtyard","blurb":"A short drive from the port, a walk to the sand and restaurants. Parking is extra.","rate":21900,"shuttle":false,"stepFree":false}', N'en', 30)
) AS s ([Id], [Area], [Title], [Body], [Locale], [SortOrder])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Area] = s.[Area], t.[Title] = s.[Title], t.[Body] = s.[Body], t.[Locale] = s.[Locale], t.[SortOrder] = s.[SortOrder]
WHEN NOT MATCHED THEN INSERT ([Id], [Area], [Title], [Body], [Locale], [SortOrder]) VALUES (s.[Id], s.[Area], s.[Title], s.[Body], s.[Locale], s.[SortOrder]);
GO

-- ref.LegalDocs: 4 rows
MERGE ref.LegalDocs AS t
USING (VALUES
  (N'terms', 202610, N'Booking terms and ticket contract', N'I have read the booking terms and ticket contract, and I accept them for everyone on this booking.', N'["This is concept text for a demonstration, not a real contract.","The cruise fare, taxes and fees, and any package are due as shown at booking. A deposit holds the stateroom; the balance is due 90 days before sailing.","Itineraries, ports and times can change for weather, safety or operational reasons. When they do, we will tell you as soon as we can.","The cancellation and change terms shown before payment are part of this contract."]'),
  (N'health', 202610, N'Health requirements', N'I understand the health requirements, and I will tell Guest Services if anyone on this booking is unwell before sailing.', N'["Guests who have symptoms of an infectious illness before boarding may be asked to see the medical team, and may be refused boarding.","You must tell us about any medical equipment, such as oxygen or a CPAP machine, so we can plan for it. Bring enough of any medicine you take, in its original packaging.","Medical care on board is available, but it is not a hospital. Travel insurance that covers medical care and evacuation is strongly recommended."]'),
  (N'age', 202610, N'Minimum age', N'I confirm that every guest meets the minimum age, and that at least one guest in each stateroom is 21 or older on the day of sailing.', N'["Babies must be at least 6 months old on the first day of the cruise.","At least one guest in each stateroom must be 21 or older on the day of sailing. Guests under 18 must sail with an adult.","You will need to show proof of age for every guest at check-in."]'),
  (N'pregnancy', 202610, N'Pregnancy policy', N'I understand the pregnancy policy.', N'["A guest who will be 24 weeks pregnant or more at any time during the cruise cannot sail.","A guest who is pregnant must bring a note from their doctor that says they are fit to travel and gives the due date.","If you cannot sail because of this policy, tell us before you travel and ask Guest Services about your options."]')
) AS s ([Id], [Version], [Title], [Statement], [Body])
ON t.[Id] = s.[Id] AND t.[Version] = s.[Version]
WHEN MATCHED THEN UPDATE SET t.[Title] = s.[Title], t.[Statement] = s.[Statement], t.[Body] = s.[Body]
WHEN NOT MATCHED THEN INSERT ([Id], [Version], [Title], [Statement], [Body]) VALUES (s.[Id], s.[Version], s.[Title], s.[Statement], s.[Body]);
GO
